(()=>{
const trigger=document.createElement('button');trigger.id='warehouse-assistant-trigger';trigger.type='button';trigger.hidden=true;trigger.setAttribute('aria-label','打开库存助手');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-controls','warehouse-floating-assistant');trigger.title='库存助手';trigger.innerHTML='<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m16 3 3.5 9.5L29 16l-9.5 3.5L16 29l-3.5-9.5L3 16l9.5-3.5L16 3Z"/><path d="m13 14 6 4"/></svg>';document.body.append(trigger);
const panel=document.createElement('section');panel.id='warehouse-floating-assistant';panel.hidden=true;panel.setAttribute('aria-label','库存助手');panel.innerHTML='<header><span class="floating-assistant-symbol">✧</span><div><h2>库存助手</h2><p>库存作业智能体</p></div><button type="button" data-close aria-label="关闭库存助手">×</button></header><div class="floating-assistant-content"><div class="floating-assistant-message">小琴，你好。可以直接描述仓储需求，让我协助查询、核对与跟进。</div><div class="floating-assistant-options"><button type="button" data-action="stock">查询库存现有量及可用量 <span>→</span></button><button type="button" data-action="transfer">创建转库单 <span>→</span></button><button type="button" data-action="daily">查看ERP与WMS库存差异 <span>→</span></button></div></div><form><label for="floating-assistant-prompt">描述你的需求</label><textarea id="floating-assistant-prompt" placeholder="例如：查询华东库存组织主控板库存…" rows="2" required></textarea><button type="submit" aria-label="发送给库存助手">↑</button></form>';document.body.append(panel);
function close(focus=false){panel.hidden=true;trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-label','打开库存助手');if(focus)trigger.focus()}
trigger.onclick=()=>{if(!panel.hidden){close();return}panel.hidden=false;trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-label','收起库存助手');panel.querySelector('textarea').focus()};panel.querySelector('[data-close]').onclick=()=>close(true);panel.addEventListener('keydown',e=>{if(e.key==='Escape')close(true)});
panel.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>{close();const action=button.dataset.action;const prompt=action==='stock'?'查询华东库存组织主控板的现有量及可用量。':action==='transfer'?'请创建转库单：华东库存组织，将原料子库 RM01 的主控板 PCB-A100 转入线边子库 WIP01，数量 200 块。':'';window.openReferenceRecommendation(action,prompt)});
panel.querySelector('form').onsubmit=e=>{e.preventDefault();const input=panel.querySelector('textarea'),text=input.value.trim();if(!text)return;close();promptBox.value=text;promptBox.dispatchEvent(new Event('input',{bubbles:true}));sendPrompt();input.value=''};
function sync(){const show=sessionStorage.getItem('yunxu-role')==='purchase-lead'&&document.body.classList.contains('conversation-entry')&&!document.body.classList.contains('choosing-role');trigger.hidden=!show;if(!show)close()}
new MutationObserver(sync).observe(document.body,{attributes:true,attributeFilter:['class']});window.addEventListener('storage',sync);sync();
})();
